<?php
namespace App\Models; use App\Domain\Admin\Enums\AdminRole; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Foundation\Auth\User as Authenticatable; use Illuminate\Notifications\Notifiable;
class User extends Authenticatable {use HasFactory,Notifiable; protected $fillable=['name','email','password','is_admin','role']; protected $hidden=['password','remember_token']; protected function casts():array{return ['email_verified_at'=>'datetime','password'=>'hashed','is_admin'=>'boolean','role'=>AdminRole::class];} public function canDo(string $permission):bool{if($this->is_admin && ($this->role===null || $this->role===AdminRole::Customer)) return true; return $this->role?->allows($permission)??false;} public function isStaff():bool{return ($this->role?->isStaff()??false)||$this->is_admin;}}
